import React from 'react';

const FALLBACK_IMAGE =
  'data:image/svg+xml,%3Csvg xmlns=%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22 viewBox=%220 0 120 120%22%3E%3Crect width=%22120%22 height=%22120%22 rx=%2218%22 fill=%22%231b2545%22%2F%3E%3Ccircle cx=%2260%22 cy=%2252%22 r=%2220%22 fill=%22%234ecdc4%22 opacity=%22.85%22%2F%3E%3Cpath d=%22M25 100c5-22 18-32 35-32s30 10 35 32%22 fill=%22%2345b7d1%22 opacity=%22.85%22%2F%3E%3C%2Fsvg%3E';

const ImageWithFallback = ({ src, alt = '', onError, ...props }) => {
  const handleError = (event) => {
    event.currentTarget.onerror = null;
    event.currentTarget.src = FALLBACK_IMAGE;
    onError?.(event);
  };

  return (
    <img
      {...props}
      src={src || FALLBACK_IMAGE}
      alt={alt}
      onError={handleError}
    />
  );
};

export default ImageWithFallback;
